<template><view class="phone-verification"><text class="field-label">手机号码</text><view v-if="verified" class="verified-phone"><text>{{masked}}</text><text class="tag green">已验证</text></view><template v-else><text v-if="!available" class="field-error">短信服务尚未开通，暂不能完成手机号验证。</text><input v-model="phone" @blur="phone=$event.detail.value" class="text-input" type="number" maxlength="11" placeholder="输入中国大陆手机号码" :disabled="busy" /><view class="code-row"><input v-model="code" @blur="code=$event.detail.value" class="text-input" type="number" maxlength="6" placeholder="6 位验证码" :disabled="busy" /><button class="ui-button btn outline small" :disabled="busy||!available||remaining>0" @click="send">{{remaining>0?remaining+' 秒后重发':'获取验证码'}}</button></view><text v-if="sentTo" class="muted tiny">已发送至 {{sentTo}}，5 分钟内有效。</text><text v-if="error" class="field-error">{{error}}</text><button class="ui-button btn outline wide section" :disabled="busy||!challenge||!available" @click="verify">{{busy?'处理中…':'验证手机号'}}</button></template><text class="muted tiny phone-help">手机号仅本人和有权限的后台人员可见。验证后如需更改，请联系平台；手机验证不能替代实名认证。</text></view></template>
<script setup>
import {ref,watch,onBeforeUnmount} from 'vue';import {session,request,loadMe} from '../lib/api'
defineProps({verified:Boolean,masked:String,available:Boolean});const emit=defineEmits(['verified'])
const phone=ref(''),code=ref(''),challenge=ref(''),sentTo=ref(''),busy=ref(false),error=ref(''),remaining=ref(0);let until=0
const timer=setInterval(()=>{remaining.value=Math.max(0,Math.ceil((until-Date.now())/1000))},1000);onBeforeUnmount(()=>clearInterval(timer))
watch(phone,()=>{challenge.value='';code.value='';sentTo.value='';error.value=''})
watch(()=>session.token,()=>{phone.value='';code.value='';challenge.value='';sentTo.value='';busy.value=false;error.value='';remaining.value=0;until=0},{flush:'sync'})
async function send(){if(busy.value)return;if(!/^1[3-9]\d{9}$/.test(phone.value)){error.value='请输入正确的 11 位手机号';return}const token=session.token,value=phone.value;busy.value=true;error.value='';try{const r=await request('/boost/me/phone/code','POST',{phone:value});if(token!==session.token||value!==phone.value)return;challenge.value=r.challengeId;sentTo.value=r.phoneMasked;until=Date.now()+r.retryAfter*1000;remaining.value=r.retryAfter}catch(e){if(token===session.token)error.value=e.message}finally{if(token===session.token)busy.value=false}}
async function verify(){if(busy.value||!challenge.value)return;if(!/^\d{6}$/.test(code.value)){error.value='请输入 6 位验证码';return}const token=session.token;busy.value=true;error.value='';try{const r=await request('/boost/me/phone/verify','POST',{challengeId:challenge.value,code:code.value});if(token===session.token){code.value='';emit('verified',r)}}catch(e){if(token===session.token){error.value=e.message;try{const user=await loadMe();if(token===session.token&&user?.playerProfile?.phoneVerified){error.value='';code.value='';emit('verified',user.playerProfile)}}catch{if(token===session.token)error.value='验证结果暂未确认，请刷新认证状态后重试'}}}finally{if(token===session.token)busy.value=false}}
</script>
<style scoped>.verified-phone{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:16px;background:#f5f6f8;border-radius:12px}.code-row{display:flex;align-items:center;gap:10px;margin:12px 0}.code-row input{min-width:0;flex:1}.code-row button{flex-shrink:0;min-height:44px}.phone-help{display:block;margin-top:12px;line-height:1.65}</style>
